        "bookName": "Exodus",
        "chapterNumber": 17,
        "verseNumber": 1,
        "text": "All the congregation of the children of Israel traveled from the wilderness of Sin, starting according to Yahweh’s commandment, and encamped in Rephidim; but there was no water for the people to drink.",
