        "bookName": "Exodus",
        "chapterNumber": 18,
        "verseNumber": 1,
        "text": "Now Jethro, the priest of Midian, Moses’ father-in-law, heard of all that God had done for Moses, and for Israel his people, how Yahweh had brought Israel out of Egypt.",
        "translation": "WEB",
        "illustrationId": "ill-exo-18",
