        "bookId": "EXO",
        "bookName": "Exodus",
        "chapterNumber": 18,
        "verseNumber": 12,
        "text": "Jethro, Moses’ father-in-law, took a burnt offering and sacrifices for God. Aaron came with all the elders of Israel, to eat bread with Moses’ father-in-law before God.",
        "translation": "WEB",
        "illustrationId": "ill-exo-18",
