        "bookName": "Exodus",
        "chapterNumber": 34,
        "verseNumber": 18,
        "text": "“You shall keep the feast of unleavened bread. Seven days you shall eat unleavened bread, as I commanded you, at the time appointed in the month Abib; for in the month Abib you came out of Egypt.",
        "translation": "WEB",
