        "bookId": "EXO",
        "bookName": "Exodus",
        "chapterNumber": 34,
        "verseNumber": 20,
        "text": "You shall redeem the firstborn of a donkey with a lamb. If you will not redeem it, then you shall break its neck. You shall redeem all the firstborn of your sons. No one shall appear before me empty.",
