        "bookId": "EXO",
        "bookName": "Exodus",
        "chapterNumber": 34,
        "verseNumber": 25,
        "text": "“You shall not offer the blood of my sacrifice with leavened bread. The sacrifice of the feast of the Passover shall not be left to the morning.",
